package ai.nexusone.service;
import ai.nexusone.dto.*; import ai.nexusone.entity.DeploymentEntity; import ai.nexusone.exception.NotFoundException; import ai.nexusone.repository.DeploymentRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service
public class DeploymentService {private final DeploymentRepository repo;public DeploymentService(DeploymentRepository r){repo=r;}public List<DeploymentEntity> findAll(){return repo.findAll();}public RiskResponse simulate(DeploymentRequest r){int s=Math.floorMod(Objects.hash(r.applicationName(),r.environment(),r.provider(),r.version()),61)+15;if("production".equalsIgnoreCase(r.environment()))s=Math.min(100,s+10);String l=s<40?"LOW":s<70?"MEDIUM":"HIGH";return new RiskResponse(s,l,s<40?List.of("Proceed with standard approval gates"):List.of("Use canary rollout","Require manual approval","Verify rollback readiness"));}public DeploymentEntity create(DeploymentRequest r){RiskResponse x=simulate(r);return repo.save(new DeploymentEntity(r.applicationName(),r.environment(),r.provider(),r.version(),x.riskScore()>=85?"PENDING_APPROVAL":"SUCCEEDED",x.riskScore()));}public DeploymentEntity rollback(String id){DeploymentEntity d=repo.findById(id).orElseThrow(()->new NotFoundException("Deployment not found: "+id));d.setStatus("ROLLED_BACK");return repo.save(d);}}
